async function requireParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (parent === null || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

/** The chain above an issue, nearest first; its length is the issue's level. */
async function ancestorsOf(orgId: OrgId, issue: Issue): Promise<Issue[]> {
  const chain: Issue[] = [];
  const seen = new Set<string>([issue.id]);
  let parentId = issue.parentId;

  while (parentId !== null && !seen.has(parentId)) {
    const parent = await issueRepo.findIssueById(orgId, parentId);
    if (parent === null) break;
    chain.push(parent);
    seen.add(parent.id);
    parentId = parent.parentId;
  }

