    includeArchived: true,
  });
  const depth = new Map<string, number>([[issueId, 0]]);
  let height = 0;

  for (const each of below) {
    const level = (depth.get(each.parentId ?? "") ?? 0) + 1;
    depth.set(each.id, level);
    height = Math.max(height, level);
  }

  return height;
}

