/**
 * Sub-issues: placement rules, listing, roll-up, cascading archive and the
 * completion notice to the parent's assignee.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import { NotFoundError } from "@/server/services/_support";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("subissues", "growth");
  other = await createTenant("subissues-other", "growth");
});

afterAll(() => {
  cleanup();
});

async function make(title: string, parentId: IssueId | null = null) {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title, parentId }),
  );
}

async function chain(length: number, prefix: string) {
  const issues = [await make(`${prefix} 0`)];
  for (let level = 1; level < length; level += 1) {
    issues.push(await make(`${prefix} ${level}`, issues[level - 1]!.id));
  }
  return issues;
}

describe("sub-issues", () => {
  it("places, moves and detaches an issue, announcing each change", async () => {
    const a = await make("Parent A");
    const b = await make("Parent B");
    const child = await make("Child");
    const events: unknown[] = [];
    const off = subscribe("issue.updated", (payload) => {
      events.push(payload);
    });

    try {
      const placed = await issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: a.id,
      });
      expect(placed.parentId).toBe(a.id);

      const moved = await issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: b.id,
      });
      expect(moved.parentId).toBe(b.id);

      const root = await issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: null,
      });
      expect(root.parentId).toBeNull();
    } finally {
      off();
    }

    expect(events).toHaveLength(3);
    expect(events[0]).toMatchObject({ issueId: child.id, changedFields: ["parentId"] });
  });

  it("guards scope, existence and archived state", async () => {
    const issue = await make("Guarded");
    const foreign = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "Foreign" }),
    );

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: other.org.id,
        issueId: foreign.id,
        parentId: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        parentId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.listSubIssues(tenant.actors.member, tenant.org.id, foreign.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const gone = await make("Archived parent");
    await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, gone.id);
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        parentId: gone.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(make("Under archived", gone.id)).rejects.toBeInstanceOf(
      AlreadyArchivedError,
    );
  });

  it("refuses cycles and trees deeper than the limit", async () => {
    const [top, , , leaf] = await chain(4, "Deep");

    const cycle = issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: top!.id,
      parentId: leaf!.id,
    });
    await expect(cycle).rejects.toBeInstanceOf(IssueHierarchyError);
    await expect(cycle).rejects.toMatchObject({ reason: "cycle" });

    await expect(make("Too deep", leaf!.id)).rejects.toMatchObject({
      reason: "too_deep",
    });

    const [shortTop] = await chain(2, "Short");
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: shortTop!.id,
        parentId: (await chain(2, "Host"))[1]!.id,
      }),
    ).rejects.toMatchObject({ reason: "too_deep" });
    expect(
      (await issueRepo.findIssueById(tenant.org.id, shortTop!.id))?.parentId,
    ).toBeNull();
  });

  it("lists live direct sub-issues and rolls up everything below", async () => {
    const parent = await make("Roll-up parent");
    const first = await make("First", parent.id);
    const second = await make("Second", parent.id);
    await make("Grandchild", first.id);
    const dropped = await make("Dropped", parent.id);
    await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, dropped.id);
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: second.id,
      status: "done",
    });

    const subs = await issueService.listSubIssues(
      tenant.actors.member,
      tenant.org.id,
      parent.id,
    );
    expect(subs.map((issue) => issue.id)).toEqual([first.id, second.id]);
    expect(
      await issueService.getIssueRollup(tenant.actors.member, tenant.org.id, parent.id),
    ).toEqual({ total: 3, open: 2, closed: 1 });
  });

  it("archives the whole subtree with one event per issue", async () => {
    const parent = await make("Archive parent");
    const child = await make("Archive child", parent.id);
    const grandchild = await make("Archive grandchild", child.id);
    const archived: unknown[] = [];
    const off = subscribe("issue.archived", (payload) => {
      archived.push(payload.issueId);
    });

    try {
      await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, child.id);
    } finally {
      off();
    }

    expect(archived.sort()).toEqual([child.id, grandchild.id].sort());
    expect(
      (await issueRepo.findIssueById(tenant.org.id, parent.id))?.archivedAt,
    ).toBeNull();
    expect(
      (await issueRepo.findIssueById(tenant.org.id, grandchild.id))?.archivedAt,
    ).not.toBeNull();
  });

  it("tells the parent's assignee once the last open sub-issue closes", async () => {
    const parent = await make("Notify parent");
    await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: parent.id,
      assigneeId: tenant.userIds.admin,
    });
    const a = await make("Notify A", parent.id);
    const b = await make("Notify B", parent.id);

    const notices = async () =>
      (
        await listNotifications(tenant.actors.admin, {
          orgId: tenant.org.id,
          recipientId: tenant.userIds.admin,
          unreadOnly: false,
          kind: ["sub_issues_completed"],
          limit: 25,
          cursor: null,
        })
      ).items.length;

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: a.id,
      status: "done",
    });
    expect(await notices()).toBe(0);

    await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, b.id);
    expect(await notices()).toBe(1);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: a.id,
      status: "canceled",
    });
    expect(await notices()).toBe(1);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: a.id,
      status: "todo",
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: a.id,
      status: "done",
    });
    expect(await notices()).toBe(2);
  });
});
